#include "../native/unit_find131.hpp"
#include <stdexcept>
#include <cstdio>
void Check(bool ok,const char* message){if(!ok)throw std::runtime_error(message);}
wht::UnitFindSource131 Selected(){wht::UnitFindSource131 v;v.source.unit=123;v.source.world=456;v.source.agent=789;v.source.id={1,2};v.source.local=0;v.info.code=0x68666f6f;v.info.x=10.25f;v.info.y=-20.5f;return v;}
int main(){try{auto target=Selected();unsigned reads=0;bool fail=false;unsigned change=0;std::string report;auto read=[&](wht::UnitFindSource131& out){out=target;++reads;if(fail)return false;if(reads==2){switch(change){case 1:++out.source.unit;break;case 2:++out.source.id.low;break;case 3:++out.source.world;break;case 4:++out.source.local;break;case 5:++out.source.agent;break;case 6:++out.info.code;break;case 7:out.info.x=NAN;break;case 8:out.info.y=INFINITY;break;case 9:out.info.x=30;break;}}return true;};auto run=[&](const std::wstring& args){reads=0;return wht::UnitFindCommand131(args,read,report);};
 Check(run(L"hfoo")&&reads==2&&report.find("Found [hfoo] in active selection at (10.2, -20.5)")!=report.npos,"matching selected rawcode and coordinates");Check(run(L" 0x68666F6F ")&&reads==2,"exact hex rawcode");Check(!run(L"Hfoo")&&report.find("not found in active selection; selected [hfoo]")!=report.npos,"case-sensitive mismatch not false positive");
 for(const auto* args:{L"",L"foo",L"hfoo extra",L"0x68666f6",L"0x68666f6g",L"0x00000000",L"hfoo\n",L"hfoo\r"})Check(!run(args)&&!reads,"malformed query no game access");Check(!run(std::wstring(L"hfoo\0x",6))&&!reads,"embedded NUL refused");
 fail=true;Check(!run(L"hfoo")&&reads==1&&report.find("position unavailable")!=report.npos,"no selected/native reader failure");fail=false;for(change=1;change<=8;++change)Check(!run(L"hfoo"),"changed unit serial world local agent rawcode or invalid position refused");change=9;Check(run(L"hfoo")&&report.find("(30.0, -20.5)")!=report.npos,"moving same unit reports latest coordinates");change=0;target.source.unit=0;Check(!run(L"hfoo"),"null unit refused");target=Selected();target.source.id={0,0};Check(!run(L"hfoo"),"invalid registry id refused");target=Selected();target.info.code=0;Check(!run(L"hfoo"),"missing type refused");
 puts("selected unit find contracts passed");return 0;}catch(const std::exception& e){puts(e.what());return 1;}}
